"""Generate the seven executable AI examples and a schema-derived capability catalogue."""
import copy,json,hashlib
from pathlib import Path
from create_evolution_example import upgraded
from change_set_schema import ENTITIES
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'AI_EXAMPLES';OUT.mkdir(exist_ok=True)
def dump(name,x):(OUT/name).write_text(json.dumps(x,indent=2)+'\n')
def entity_hash(x):return hashlib.sha256(json.dumps(x,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()).hexdigest()
s=upgraded(5,start='2026-11-09',end='2026-11-22');s.update(dutyBindingMode='GLOBAL',schemaVersion=4,id='ai-five-person-business',label='Five-person business',policies=[],groups=[],constraints=[],baseConstraintIds=[],allowedShifts=[])
s['attributeDefinitions']=[dict(id='contract',label='Contract',type='ENUM',values=['FULL_TIME','PART_TIME'],default='FULL_TIME'),dict(id='manager',label='Manager',type='BOOLEAN',default=False),dict(id='eligible',label='Closing qualified',type='BOOLEAN',default=True)]
s['employees']=[dict(id=name.lower(),label=name,typeId='staff',attributes={'manager':i<2},employment={'validFrom':'2026-01-01'},versions=[]) for i,name in enumerate(['Anna','Giuseppe','Marco','Luca','Sara'])]
s['shifts'][0]['intervals']=[dict(start='09:00',end='17:00',endDayOffset=0)];s['shifts'][1]['intervals']=[dict(start='16:00',end='21:00',endDayOffset=0)];s['shifts'][1]['fairnessTags']=['closing-burden']
s['workPatterns']=[dict(id=id,label=label,versions=[dict(validFrom='2026-01-01',weekdays=[1,2,3,4,5,6,7],shiftIds=['regular','closing','off'],weekdayShifts=([dict(weekday=d,shiftIds=['regular','off']) for d in [1,2,3,4]] if id=='part' else []))]) for id,label in [('full','Full-time work'),('part','Part-time; closing only Friday or weekend')]]
s['workPatternAssignmentRules']=[dict(id=id,label=label,enabled=True,selector={'where':dict(op='EQ',attributeId='contract',value=value)},workPatternId=pattern,priority=10,validFrom='2026-01-01') for id,label,value,pattern in [('full-rule','Full-time contracts','FULL_TIME','full'),('part-rule','Part-time contracts','PART_TIME','part')]]
s['weekProfiles']=[dict(id=id,label=label,offWeekdays=off,holidayMode=holiday,constraintIds=[],policyIds=[]) for id,label,off,holiday in [('ordinary','Ordinary week',[6,7],'OFF'),('special','Special week',[],'NORMAL')]];s['weekConfiguration']['defaultProfileId']='ordinary'
selector={'typeIds':['staff'],'where':dict(op='EQ',attributeId='eligible',value=True)}
s['dutyRequirements']=[dict(id='closing-duty',label='One daily closing',mode='RESPONSIBILITY',shiftIds=['closing'],levels=[dict(selector=selector,level=0)],comparison='EQ',count=1,intervals=[dict(start='20:00',end='21:00',endDayOffset=0)],scope={'weekdays':[1,2,3,4,5],'dayType':'NON_HOLIDAY'},preferencePriority=0,exclusiveGroup='daily-duties',bindAssignments=True)]
s['allowedShifts']=[dict(id='normal-work',selector={},shiftIds=['regular','closing'],scope={'weekdays':[1,2,3,4,5],'dayType':'NON_HOLIDAY'},allowRequiredRest=True)]
p=dict(id='closing-fairness',label='Combined closing fairness',revision=1,active=True,draft=False,dependencies=[],constraints=[],sharedConstraintIds=[],constraintSetIds=[],objective=dict(id='closing-count',label='All eligible current and future staff',type='CUMULATIVE_FAIRNESS',mode='CONTINUOUS_BALANCED',measure='COUNT',selector=selector,shiftIds=[],fairnessTags=['closing-burden'],participation='AVAILABILITY_WEIGHTED',metrics=['MAX_ABSOLUTE_PREFIX_DEVIATION','SUM_ABSOLUTE_PREFIX_DEVIATIONS','FINAL_ABSOLUTE_DEVIATION'],priority=0))
s['policies']=[p];s['spacingRules']=[dict(id='preferred-gap',label='Avoid adjacent closings',selector=selector,shiftIds=[],fairnessTags=['closing-burden'],scope={},mode='SOFT',unit='CALENDAR',minimumGap=2,normalShiftIds=['regular'],penalty='CLOSE_PAIRS',priority=50)];s['search']['maxTimeSeconds']=10
dump('01-create-scenario.json',s)
def change(name,desc,ops,hard=False,referenceDate='2026-11-09'):
 d=dict(format='rostercore.scenario-change-set',schemaVersion=1,id=name,scenarioId=s['id'],expectedRevision=1,allowHardRuleChanges=hard,description=desc,referenceDate=referenceDate,operations=ops);dump(name+'.json',d)
change('02-anna-part-time','From 1 March 2027 Anna changes to part time.',[dict(op='UPDATE_EMPLOYEE',employeeId='anna',effectiveFrom='2027-03-01',patch={'attributes':{'contract':'PART_TIME'}})])
change('03-giuseppe-vacation','Giuseppe is away 10–17 August 2027 inclusive.',[dict(op='CREATE_AVAILABILITY',value=dict(id='giuseppe-vacation',selector={'employeeIds':['giuseppe']},scope={'start':'2027-08-10','end':'2027-08-17'},state='ABSENT'))])
change('04-marco-unexpected-absence','Reference today is 9 November 2026; Marco is absent today and the following two days. Regenerate the plan.',[dict(op='CREATE_AVAILABILITY',value=dict(id='marco-unplanned',selector={'employeeIds':['marco']},scope={'start':'2026-11-09','end':'2026-11-11'},state='ABSENT'))])
change('05-evening-shift','Add an evening shift from 16:00 to 21:00; no coverage requirement is implied.',[dict(op='CREATE_SHIFT',value=dict(id='evening',label='Evening',kind='WORKING',intervals=[dict(start='16:00',end='21:00',endDayOffset=0)],fairnessTags=[]))],True)
change('06-special-sunday-manager','During special weeks, at least one manager must be physically present on Sunday 09:00–12:00.',[dict(op='CREATE_COVERAGE',value=dict(id='sunday-manager',label='Sunday manager presence',mode='PRESENCE',shiftIds=['regular'],levels=[dict(selector={'where':dict(op='EQ',attributeId='manager',value=True)},level=0)],comparison='GE',count=1,intervals=[dict(start='09:00',end='12:00',endDayOffset=0)],scope={'weekProfileIds':['special'],'weekdays':[7]},preferencePriority=0))],True)
replacement=copy.deepcopy(p);replacement['revision']=2;replacement['label']='Closing fairness including new eligible colleagues'
change('07-new-colleague-fairness','Include new eligible hires through the dynamic staff selector and preserve the existing objective identity and historical quota definition.',[dict(op='CREATE_EMPLOYEE',value=dict(id='new-colleague',label='New colleague',typeId='staff',attributes={'eligible':True},employment={'validFrom':'2026-11-16'},versions=[])),dict(op='REPLACE_POLICY',value=replacement,expectedEntityHash=entity_hash(p))],True)
schema=json.loads((ROOT/'schemas/scenario-change-set.schema.json').read_text());operations=schema['definitions']['scenarioChangeSet']['properties']['operations']['items']['oneOf']
cap=dict(format='rostercore.ai-capabilities',schemaVersion=1,engineVersion='0.5.0',scenarioVersions=[1,2,3,4],preferredScenarioVersion=4,documents=['rostercore.scenario','rostercore.scenario-change-set','rostercore.planning-policy','rostercore.hr-events','rostercore.history-contexts','rostercore.schedule-archive','rostercore.workspace-backup'],operations=[dict(name=x['properties']['op']['enum'][0],required=x['required']) for x in operations],entityCollections=ENTITIES,timeConventions={'scenarioPeriod':'inclusive dates','scopePeriod':'inclusive dates','effectiveVersions':'[validFrom,validTo)','employmentEnd':'exclusive','weeks':'ISO Monday','today':'explicit referenceDate; never infer','normalWorkGap':'actual intervening configured normal WORKING assignments','calendarGap':'difference between assignment dates'},priorities=['all hard constraints','lexicographic fallback worst level first','desired week frequency','stability if BEFORE_FAIRNESS','fairness and soft spacing by ascending priority','stability if AFTER_FAIRNESS'],unsupported=['arbitrary JSON pointers','code execution','partial-day absence','minute-based fairness','burden points','arbitrary IANA elapsed-time zones','automatic hard-rule relaxation','automatic publication or completion','remote mandatory AI service'],examples=[x.name for x in sorted(OUT.glob('*.json'))])
(ROOT/'AI_CAPABILITIES.json').write_text(json.dumps(cap,indent=2)+'\n')
